import fs from 'fs';
import path from 'path';

// Business stamp artwork (generated by scripts/make-stamp.ts, committed under
// public/brand/). Read once per process and handed to @react-pdf as data URLs.
// Returns undefined if the file is missing so a PDF still renders without it.
const cache = new Map<string, string | undefined>();

function load(file: string): string | undefined {
  if (!cache.has(file)) {
    try {
      const buf = fs.readFileSync(path.join(process.cwd(), 'public', 'brand', file));
      cache.set(file, `data:image/png;base64,${buf.toString('base64')}`);
    } catch (err) {
      console.error(`[pdf/stamp] ${file} not found — rendering without stamp`, err);
      cache.set(file, undefined);
    }
  }
  return cache.get(file);
}

/** Coloured stamp for A4 documents (in place of the signature box). */
export const stampDataUrl = () => load('stamp.png');
/** Light grey stamp for the thermal receipt watermark. */
export const thermalStampDataUrl = () => load('stamp-thermal.png');
